# Glass pavilion: leather chair, terrazzo floor, black mirror slabs, snowy mountains. Every object, texture and
# mountain is generated by this script. No downloaded models, images or HDRIs.
#   blender -b --python scene.py -- <outdir> <a:b:step | f1,f2,...> <res_w> <spp>
import bpy, bmesh, math, os, sys, time
import numpy as np
from mathutils import Vector, Euler
HERE = os.path.dirname(os.path.abspath(__file__))
FPS = 24; END = 480                      # 20 s
ASPECT = 2.39

bpy.ops.wm.read_factory_settings(use_empty=True)
sc = bpy.context.scene
sc.render.engine = 'CYCLES'; sc.cycles.device = 'CPU'
if os.environ.get('BUBO_GPU'):
    prefs = bpy.context.preferences.addons['cycles'].preferences
    for typ in ('OPTIX', 'CUDA', 'METAL'):
        try:
            prefs.compute_device_type = typ; prefs.get_devices()
            devs = [d for d in prefs.devices if d.type == typ]
            if devs:
                for d in prefs.devices: d.use = (d.type == typ)
                sc.cycles.device = 'GPU'; print('GPU', typ, [d.name for d in devs]); break
        except Exception as e: print('gpu', typ, 'unavailable:', e)
sc.cycles.use_denoising = True
try: sc.cycles.denoiser = 'OPENIMAGEDENOISE'
except Exception: pass
sc.cycles.max_bounces = 6; sc.cycles.diffuse_bounces = 3; sc.cycles.glossy_bounces = 3
sc.cycles.transparent_max_bounces = 16; sc.cycles.transmission_bounces = 2
sc.cycles.caustics_reflective = False; sc.cycles.caustics_refractive = False
sc.cycles.use_adaptive_sampling = True; sc.cycles.adaptive_threshold = 0.03
sc.cycles.sample_clamp_indirect = 8.0
if os.environ.get('HQ'):
    sc.cycles.adaptive_threshold = 0.01; sc.cycles.max_bounces = 8; sc.cycles.diffuse_bounces = 4; sc.cycles.glossy_bounces = 4
sc.render.fps = FPS; sc.render.use_persistent_data = True
sc.render.use_motion_blur = True; sc.render.motion_blur_shutter = 0.5
sc.frame_start = 0; sc.frame_end = END - 1
try: sc.view_settings.view_transform = 'AgX'; sc.view_settings.look = 'AgX - Medium High Contrast'
except Exception: sc.view_settings.view_transform = 'Filmic'
sc.view_settings.exposure = float(os.environ.get('EXPO', '0.0'))

def smooth(x): x = min(1.0, max(0.0, x)); return x * x * (3 - 2 * x)
def link(o): sc.collection.objects.link(o); return o
def newmat(name):
    m = bpy.data.materials.new(name)
    try: m.use_nodes = True
    except Exception: pass
    return m, m.node_tree.nodes, m.node_tree.links
def node(N, typ, **kw):
    n = N.new(typ)
    for k, v in kw.items():
        if k in n.inputs: n.inputs[k].default_value = v
        else: setattr(n, k, v)
    return n

def box_obj(name, size, loc, mat, rot=(0, 0, 0), bevel=0.0, seg=3, subsurf=0, cast=0.0):
    me = bpy.data.meshes.new(name); bm = bmesh.new()
    bmesh.ops.create_cube(bm, size=1.0)
    for v in bm.verts: v.co = Vector((v.co.x * size[0], v.co.y * size[1], v.co.z * size[2]))
    bm.to_mesh(me); bm.free()
    o = link(bpy.data.objects.new(name, me)); o.location = loc; o.rotation_euler = rot
    if bevel > 0:
        b = o.modifiers.new('bev', 'BEVEL'); b.width = bevel; b.segments = seg; b.limit_method = 'NONE'
        try: b.harden_normals = False
        except Exception: pass
    if subsurf:
        s = o.modifiers.new('sub', 'SUBSURF'); s.levels = subsurf; s.render_levels = subsurf
    if cast:
        c = o.modifiers.new('cast', 'CAST'); c.factor = cast; c.use_x = c.use_y = c.use_z = True
    me.materials.append(mat)
    for p in me.polygons: p.use_smooth = True
    return o

def cyl_obj(name, r, a, b, mat, verts=24):
    a, b = Vector(a), Vector(b); d = b - a
    bpy.ops.mesh.primitive_cylinder_add(vertices=verts, radius=r, depth=d.length, location=(a + b) / 2)
    o = bpy.context.active_object; o.name = name
    o.rotation_euler = d.to_track_quat('Z', 'Y').to_euler()
    o.data.materials.append(mat)
    for p in o.data.polygons: p.use_smooth = True
    return o

# ---------------------------------------------------------------- materials
def mat_terrazzo():
    m, N, L = newmat('terrazzo'); b = N['Principled BSDF']
    tc = node(N, 'ShaderNodeTexCoord')
    def chips(scale, rnd, thr):
        v = node(N, 'ShaderNodeTexVoronoi', feature='F1'); v.inputs['Scale'].default_value = scale
        v.inputs['Randomness'].default_value = rnd; L.new(tc.outputs['Object'], v.inputs['Vector'])
        # distance to cell edge -> chip shape: small cells read as stone fragments
        e = node(N, 'ShaderNodeTexVoronoi', feature='DISTANCE_TO_EDGE'); e.inputs['Scale'].default_value = scale
        e.inputs['Randomness'].default_value = rnd; L.new(tc.outputs['Object'], e.inputs['Vector'])
        r = node(N, 'ShaderNodeMapRange'); L.new(e.outputs['Distance'], r.inputs[0])
        r.inputs[1].default_value = 0.05; r.inputs[2].default_value = 0.09
        sel = node(N, 'ShaderNodeMath', operation='GREATER_THAN'); L.new(v.outputs['Color'], sel.inputs[0])
        sel.inputs[1].default_value = thr
        mk = node(N, 'ShaderNodeMath', operation='MULTIPLY'); L.new(r.outputs[0], mk.inputs[0]); L.new(sel.outputs[0], mk.inputs[1])
        return mk, v
    base = node(N, 'ShaderNodeTexNoise'); base.inputs['Scale'].default_value = 3.0; base.inputs['Detail'].default_value = 6
    L.new(tc.outputs['Object'], base.inputs['Vector'])
    bramp = node(N, 'ShaderNodeValToRGB'); L.new(base.outputs['Fac'], bramp.inputs[0])
    bramp.color_ramp.elements[0].color = (0.70, 0.55, 0.38, 1); bramp.color_ramp.elements[1].color = (0.78, 0.64, 0.46, 1)
    col = bramp.outputs['Color']
    for scale, rnd, thr, c in ((16, 1.0, 0.55, (0.95, 0.93, 0.89)), (28, 1.0, 0.62, (0.16, 0.14, 0.12)),
                               (11, 1.0, 0.86, (0.80, 0.55, 0.28)), (45, 1.0, 0.5, (0.90, 0.88, 0.84))):
        mk, v = chips(scale, rnd, thr)
        mx = node(N, 'ShaderNodeMix', data_type='RGBA'); L.new(mk.outputs[0], mx.inputs['Factor'])
        L.new(col, mx.inputs[6]); mx.inputs[7].default_value = (*c, 1); col = mx.outputs[2]
    L.new(col, b.inputs['Base Color'])
    rn = node(N, 'ShaderNodeTexNoise'); rn.inputs['Scale'].default_value = 1.5
    L.new(tc.outputs['Object'], rn.inputs['Vector'])
    rr = node(N, 'ShaderNodeMapRange'); L.new(rn.outputs['Fac'], rr.inputs[0]); rr.inputs[3].default_value = 0.32; rr.inputs[4].default_value = 0.52
    L.new(rr.outputs[0], b.inputs['Roughness'])
    return m

def mat_leather():
    m, N, L = newmat('leather'); b = N['Principled BSDF']
    tc = node(N, 'ShaderNodeTexCoord')
    n = node(N, 'ShaderNodeTexNoise'); n.inputs['Scale'].default_value = 6; n.inputs['Detail'].default_value = 8
    L.new(tc.outputs['Object'], n.inputs['Vector'])
    cr = node(N, 'ShaderNodeValToRGB'); L.new(n.outputs['Fac'], cr.inputs[0])
    cr.color_ramp.elements[0].color = (0.17, 0.075, 0.03, 1); cr.color_ramp.elements[1].color = (0.34, 0.15, 0.06, 1)
    L.new(cr.outputs['Color'], b.inputs['Base Color'])
    rr = node(N, 'ShaderNodeMapRange'); L.new(n.outputs['Fac'], rr.inputs[0]); rr.inputs[3].default_value = 0.30; rr.inputs[4].default_value = 0.55
    L.new(rr.outputs[0], b.inputs['Roughness'])
    for k, v in (('Coat Weight', 0.12), ('Coat Roughness', 0.3),):
        if k in b.inputs: b.inputs[k].default_value = v
    grain = node(N, 'ShaderNodeTexVoronoi'); grain.inputs['Scale'].default_value = 900; L.new(tc.outputs['Object'], grain.inputs['Vector'])
    wr = node(N, 'ShaderNodeTexNoise'); wr.inputs['Scale'].default_value = 28; wr.inputs['Detail'].default_value = 4
    wr.inputs['Distortion'].default_value = 1.5; L.new(tc.outputs['Object'], wr.inputs['Vector'])
    add = node(N, 'ShaderNodeMath', operation='ADD'); L.new(grain.outputs['Distance'], add.inputs[0]); L.new(wr.outputs['Fac'], add.inputs[1])
    bump = node(N, 'ShaderNodeBump'); bump.inputs['Strength'].default_value = 0.12; bump.inputs['Distance'].default_value = 0.002
    L.new(add.outputs[0], bump.inputs['Height']); L.new(bump.outputs['Normal'], b.inputs['Normal'])
    return m

def mat_simple(name, color, rough, metal=0.0, aniso=0.0):
    m, N, L = newmat(name); b = N['Principled BSDF']
    b.inputs['Base Color'].default_value = (*color, 1); b.inputs['Roughness'].default_value = rough
    b.inputs['Metallic'].default_value = metal
    if aniso and 'Anisotropic' in b.inputs: b.inputs['Anisotropic'].default_value = aniso
    return m

def mat_glass():
    m, N, L = newmat('glass'); out = N['Material Output']; N.remove(N['Principled BSDF'])
    tr = node(N, 'ShaderNodeBsdfTransparent'); tr.inputs['Color'].default_value = (0.96, 0.975, 0.97, 1)
    gl = node(N, 'ShaderNodeBsdfGlossy'); gl.inputs['Roughness'].default_value = 0.0
    fr = node(N, 'ShaderNodeFresnel'); fr.inputs['IOR'].default_value = 1.5
    mx = node(N, 'ShaderNodeMixShader'); L.new(fr.outputs[0], mx.inputs[0]); L.new(tr.outputs[0], mx.inputs[1]); L.new(gl.outputs[0], mx.inputs[2])
    lp = node(N, 'ShaderNodeLightPath'); tr2 = node(N, 'ShaderNodeBsdfTransparent')
    mx2 = node(N, 'ShaderNodeMixShader'); L.new(lp.outputs['Is Shadow Ray'], mx2.inputs[0])
    L.new(mx.outputs[0], mx2.inputs[1]); L.new(tr2.outputs[0], mx2.inputs[2]); L.new(mx2.outputs[0], out.inputs['Surface'])
    return m

def mat_terrain():
    m, N, L = newmat('terrain'); b = N['Principled BSDF']; out = N['Material Output']
    tc = node(N, 'ShaderNodeTexCoord'); geo = node(N, 'ShaderNodeNewGeometry')
    sep = node(N, 'ShaderNodeSeparateXYZ'); L.new(geo.outputs['Position'], sep.inputs[0])
    nsep = node(N, 'ShaderNodeSeparateXYZ'); L.new(geo.outputs['Normal'], nsep.inputs[0])
    # large-scale breakup so the snow line wanders
    br = node(N, 'ShaderNodeTexNoise'); br.inputs['Scale'].default_value = 0.012; br.inputs['Detail'].default_value = 10
    br.inputs['Roughness'].default_value = 0.62; L.new(tc.outputs['Object'], br.inputs['Vector'])
    # streaks: noise stretched along height, so snow and rock run down the fall line like gullies
    stv = node(N, 'ShaderNodeVectorMath', operation='MULTIPLY'); L.new(tc.outputs['Object'], stv.inputs[0])
    stv.inputs[1].default_value = (1.0, 1.0, 0.18)
    fine = node(N, 'ShaderNodeTexNoise'); fine.inputs['Scale'].default_value = 0.11; fine.inputs['Detail'].default_value = 12
    fine.inputs['Roughness'].default_value = 0.68; L.new(stv.outputs[0], fine.inputs['Vector'])
    # snow where the slope is gentle enough and the ground is high enough
    s0 = node(N, 'ShaderNodeMath', operation='MULTIPLY_ADD'); L.new(fine.outputs['Fac'], s0.inputs[0])
    s0.inputs[1].default_value = 0.40; L.new(nsep.outputs['Z'], s0.inputs[2])
    s1 = node(N, 'ShaderNodeMath', operation='MULTIPLY_ADD'); L.new(br.outputs['Fac'], s1.inputs[0])
    s1.inputs[1].default_value = 0.30; L.new(s0.outputs[0], s1.inputs[2])
    zb = node(N, 'ShaderNodeMath', operation='MULTIPLY_ADD'); L.new(sep.outputs['Z'], zb.inputs[0]); zb.inputs[1].default_value = 0.0011
    zb.inputs[2].default_value = -0.17
    s2 = node(N, 'ShaderNodeMath', operation='ADD'); L.new(s1.outputs[0], s2.inputs[0]); L.new(zb.outputs[0], s2.inputs[1])
    slope = node(N, 'ShaderNodeMapRange'); L.new(s2.outputs[0], slope.inputs[0]); slope.inputs[1].default_value = 0.95; slope.inputs[2].default_value = 0.99
    h1 = node(N, 'ShaderNodeMath', operation='MULTIPLY_ADD'); L.new(br.outputs['Fac'], h1.inputs[0])
    h1.inputs[1].default_value = 90.0; L.new(sep.outputs['Z'], h1.inputs[2])
    alt = node(N, 'ShaderNodeMapRange'); L.new(h1.outputs[0], alt.inputs[0]); alt.inputs[1].default_value = 55; alt.inputs[2].default_value = 120
    snow = node(N, 'ShaderNodeMath', operation='MULTIPLY'); L.new(slope.outputs[0], snow.inputs[0]); L.new(alt.outputs[0], snow.inputs[1])
    # streaky rock texture
    strata = node(N, 'ShaderNodeTexWave', wave_type='BANDS', bands_direction='Z'); strata.inputs['Scale'].default_value = 0.022
    strata.inputs['Distortion'].default_value = 14.0; strata.inputs['Detail'].default_value = 4; L.new(tc.outputs['Object'], strata.inputs['Vector'])
    rmix = node(N, 'ShaderNodeMath', operation='MULTIPLY_ADD'); L.new(strata.outputs['Fac'], rmix.inputs[0]); rmix.inputs[1].default_value = 0.12
    L.new(fine.outputs['Fac'], rmix.inputs[2])
    rk = node(N, 'ShaderNodeValToRGB'); L.new(rmix.outputs[0], rk.inputs[0])
    rk.color_ramp.elements[0].color = (0.02, 0.021, 0.024, 1); rk.color_ramp.elements[1].color = (0.15, 0.13, 0.11, 1)
    # valley meadow below the rock
    tree = node(N, 'ShaderNodeTexVoronoi'); tree.inputs['Scale'].default_value = 0.16; L.new(tc.outputs['Object'], tree.inputs['Vector'])
    trm = node(N, 'ShaderNodeMath', operation='MULTIPLY_ADD'); L.new(tree.outputs['Distance'], trm.inputs[0]); trm.inputs[1].default_value = 0.6
    L.new(br.outputs['Fac'], trm.inputs[2])
    gr = node(N, 'ShaderNodeValToRGB'); L.new(trm.outputs[0], gr.inputs[0])
    gr.color_ramp.elements[0].color = (0.006, 0.012, 0.006, 1); gr.color_ramp.elements[1].color = (0.045, 0.05, 0.028, 1)
    low = node(N, 'ShaderNodeMapRange'); L.new(sep.outputs['Z'], low.inputs[0]); low.inputs[1].default_value = 15; low.inputs[2].default_value = 60
    c1 = node(N, 'ShaderNodeMix', data_type='RGBA'); L.new(low.outputs[0], c1.inputs['Factor']); L.new(gr.outputs['Color'], c1.inputs[6]); L.new(rk.outputs['Color'], c1.inputs[7])
    c2 = node(N, 'ShaderNodeMix', data_type='RGBA'); L.new(snow.outputs[0], c2.inputs['Factor']); L.new(c1.outputs[2], c2.inputs[6])
    c2.inputs[7].default_value = (0.86, 0.89, 0.95, 1)
    L.new(c2.outputs[2], b.inputs['Base Color'])
    rr = node(N, 'ShaderNodeMapRange'); L.new(snow.outputs[0], rr.inputs[0]); rr.inputs[3].default_value = 0.95; rr.inputs[4].default_value = 0.5
    for k_ in ('Specular IOR Level', 'Specular'):
        if k_ in b.inputs: b.inputs[k_].default_value = 0.15
    L.new(rr.outputs[0], b.inputs['Roughness'])
    crev = node(N, 'ShaderNodeTexVoronoi', feature='DISTANCE_TO_EDGE'); crev.inputs['Scale'].default_value = 0.05
    L.new(stv.outputs[0], crev.inputs['Vector'])
    micro = node(N, 'ShaderNodeTexNoise'); micro.inputs['Scale'].default_value = 0.9; micro.inputs['Detail'].default_value = 10
    micro.inputs['Roughness'].default_value = 0.7; L.new(tc.outputs['Object'], micro.inputs['Vector'])
    bump0 = node(N, 'ShaderNodeBump'); bump0.inputs['Strength'].default_value = 0.5; bump0.inputs['Distance'].default_value = 0.8
    L.new(crev.outputs['Distance'], bump0.inputs['Height'])
    bump1 = node(N, 'ShaderNodeBump'); bump1.inputs['Strength'].default_value = 0.4; bump1.inputs['Distance'].default_value = 0.6
    L.new(fine.outputs['Fac'], bump1.inputs['Height']); L.new(bump0.outputs['Normal'], bump1.inputs['Normal'])
    bump = node(N, 'ShaderNodeBump'); bump.inputs['Strength'].default_value = 0.3; bump.inputs['Distance'].default_value = 0.2
    L.new(micro.outputs['Fac'], bump.inputs['Height']); L.new(bump1.outputs['Normal'], bump.inputs['Normal'])
    L.new(bump.outputs['Normal'], b.inputs['Normal'])
    # aerial perspective: blend toward the horizon haze with distance from the camera
    cam = node(N, 'ShaderNodeCameraData')
    hz = node(N, 'ShaderNodeMath', operation='MULTIPLY'); L.new(cam.outputs['View Distance'], hz.inputs[0]); hz.inputs[1].default_value = -1 / 3600.0
    ex = node(N, 'ShaderNodeMath', operation='EXPONENT'); L.new(hz.outputs[0], ex.inputs[0])
    inv = node(N, 'ShaderNodeMath', operation='SUBTRACT'); inv.inputs[0].default_value = 1.0; L.new(ex.outputs[0], inv.inputs[1])
    cl = node(N, 'ShaderNodeMath', operation='MULTIPLY', use_clamp=True); L.new(inv.outputs[0], cl.inputs[0]); cl.inputs[1].default_value = float(os.environ.get('HZ', '0.10'))
    neg = node(N, 'ShaderNodeVectorMath', operation='SCALE'); L.new(geo.outputs['Incoming'], neg.inputs[0]); neg.inputs['Scale'].default_value = -1.0
    hs = N.new('ShaderNodeTexSky'); L.new(neg.outputs[0], hs.inputs[0]); hs.sky_type = 'MULTIPLE_SCATTERING'; SKYNODES.append(hs)
    em = node(N, 'ShaderNodeEmission'); L.new(hs.outputs['Color'], em.inputs['Color']); em.inputs['Strength'].default_value = SKY_K
    mx = node(N, 'ShaderNodeMixShader'); L.new(cl.outputs[0], mx.inputs[0]); L.new(b.outputs[0], mx.inputs[1]); L.new(em.outputs[0], mx.inputs[2])
    L.new(mx.outputs[0], out.inputs['Surface'])
    return m

HAZE = (0.42, 0.52, 0.68, 1)
SKYNODES = []
SKY_K = float(os.environ.get('SKY', '0.16'))
SUN_EL, SUN_AZ = math.radians(17), math.radians(-24)
M_TERR = mat_terrazzo(); M_LEATH = mat_leather(); M_GLASS = mat_glass()
M_BLACK = mat_simple('mirror_black', (0.004, 0.004, 0.005), 0.025)
M_FRAME = mat_simple('frame', (0.012, 0.012, 0.012), 0.35, 0.6)
M_CEIL = mat_simple('ceiling', (0.035, 0.034, 0.033), 0.75)
M_STEEL = mat_simple('steel', (0.78, 0.76, 0.73), 0.22, 1.0, aniso=0.5)
M_TERRAIN = mat_terrain()

# ---------------------------------------------------------------- pavilion
X0, X1, Y0, Y1, H = -8.0, 8.0, -6.0, 7.0, 4.3
box_obj('floor', ((X1 - X0) + 0.6, (Y1 - Y0) + 0.6, 0.5), ((X0 + X1) / 2, (Y0 + Y1) / 2, -0.25), M_TERR, bevel=0.01, seg=2)
box_obj('ceiling', ((X1 - X0) + 1.6, (Y1 - Y0) + 1.6, 0.45), ((X0 + X1) / 2, (Y0 + Y1) / 2, H + 0.225), M_CEIL, bevel=0.01, seg=2)
def glass_wall(a, b):
    a, b = Vector(a), Vector(b); d = b - a; n = int(round(d.length / 1.6)); ang = math.atan2(d.y, d.x)
    me = bpy.data.meshes.new('glass'); bm = bmesh.new()
    vs = [bm.verts.new(p) for p in ((a.x, a.y, 0.02), (b.x, b.y, 0.02), (b.x, b.y, H), (a.x, a.y, H))]
    bm.faces.new(vs); bm.to_mesh(me); bm.free()
    g = link(bpy.data.objects.new('glass', me)); me.materials.append(M_GLASS)
    for i in range(n + 1):
        p = a + d * (i / n)
        box_obj('mullion', (0.06, 0.07, H), (p.x, p.y, H / 2), M_FRAME, rot=(0, 0, ang))
    mid = (a + b) / 2
    box_obj('sill', (d.length, 0.08, 0.06), (mid.x, mid.y, 0.03), M_FRAME, rot=(0, 0, ang))
    box_obj('head', (d.length, 0.08, 0.08), (mid.x, mid.y, H - 0.04), M_FRAME, rot=(0, 0, ang))
    box_obj('transom', (d.length, 0.05, 0.05), (mid.x, mid.y, 3.05), M_FRAME, rot=(0, 0, ang))
glass_wall((X0, Y1, 0), (X1, Y1, 0)); glass_wall((X1, Y0, 0), (X1, Y1, 0))
glass_wall((X0, Y0, 0), (X0, Y1, 0)); glass_wall((X0, Y0, 0), (X1, Y0, 0))

SLABS = [(-4.9, 5.0, 1.10, 1.3, 0.18), (3.7, 5.0, -0.35, 1.1, -0.22), (-5.6, 0.8, 1.25, 1.4, 0.15),
         (5.6, -0.4, 1.40, 1.2, -0.12), (2.8, -3.8, -0.18, 1.0, -0.16),
         (6.4, 3.0, 0.9, 0.9, 0.10)]
for i, (x, y, r, w, spin) in enumerate(SLABS):
    o = box_obj(f'slab{i}', (w, 0.14, H - 0.02), (x, y, H / 2), M_BLACK, rot=(0, 0, r), bevel=0.006, seg=2)
    o.rotation_euler.z = r; o.keyframe_insert('rotation_euler', index=2, frame=0)
    o.rotation_euler.z = r + spin; o.keyframe_insert('rotation_euler', index=2, frame=END)

# ---------------------------------------------------------------- chair (faces +Y)
CH = Vector((0, 0, 0))
def prism(name, prof, x0, x1, mat, bev=0.03, sub=2, cast=0.0):
    """Side profile (y, z) extruded across x: one upholstered piece."""
    me = bpy.data.meshes.new(name); bm = bmesh.new()
    A = [bm.verts.new((x0, y, z)) for y, z in prof]; B = [bm.verts.new((x1, y, z)) for y, z in prof]
    bm.faces.new(A[::-1]); bm.faces.new(B)
    n = len(prof)
    for i in range(n):
        j = (i + 1) % n; bm.faces.new((A[i], A[j], B[j], B[i]))
    bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
    bm.to_mesh(me); bm.free()
    o = link(bpy.data.objects.new(name, me)); o.location = CH
    m = o.modifiers.new('bev', 'BEVEL'); m.width = bev; m.segments = 4; m.limit_method = 'NONE'
    sm = o.modifiers.new('sub', 'SUBSURF'); sm.levels = sub; sm.render_levels = sub
    if cast:
        c = o.modifiers.new('cast', 'CAST'); c.factor = cast
    me.materials.append(mat)
    for f in me.polygons: f.use_smooth = True
    return o
def part(name, size, loc, rot=(0, 0, 0), bev=0.035, cast=0.0, mat=None):
    return box_obj(name, size, CH + Vector(loc), mat or M_LEATH, rot=rot, bevel=bev, seg=5, subsurf=2, cast=cast)
TILT = math.radians(-12)
# outer shell: seat platform + tall reclined back in one upholstered piece
shell = [(0.40, 0.21), (0.40, 0.40), (-0.20, 0.38), (-0.36, 1.12), (-0.50, 1.14), (-0.47, 0.21)]
