# ---------------------------------------------------------------- mountains (numpy heightfield)
def perlin(x, y, seed):
    xi = np.floor(x); yi = np.floor(y); xf = x - xi; yf = y - yi
    def grad(i, j):
        h = np.sin(i * 127.1 + j * 311.7 + seed * 74.7) * 43758.5453
        a = (h - np.floor(h)) * 6.2831853
        return np.cos(a), np.sin(a)
    def dot(i, j, dx, dy):
        gx, gy = grad(i, j); return gx * dx + gy * dy
    u = xf * xf * xf * (xf * (xf * 6 - 15) + 10); v = yf * yf * yf * (yf * (yf * 6 - 15) + 10)
    n00 = dot(xi, yi, xf, yf); n10 = dot(xi + 1, yi, xf - 1, yf)
    n01 = dot(xi, yi + 1, xf, yf - 1); n11 = dot(xi + 1, yi + 1, xf - 1, yf - 1)
    return (n00 * (1 - u) + n10 * u) * (1 - v) + (n01 * (1 - u) + n11 * u) * v
def ridged(x, y, octaves, seed):
    tot = np.zeros_like(x); amp = 1.0; freq = 1.0; w = np.ones_like(x)
    for o in range(octaves):
        n = 1.0 - np.abs(perlin(x * freq, y * freq, seed + o * 13))
        n = n * n * w; w = np.clip(n * 1.6, 0, 1)
        tot += n * amp; amp *= 0.5; freq *= 2.03
    return tot
SZ = 2600.0; RES = int(os.environ.get('TERRAIN_RES', '1400'))
g = np.linspace(-SZ / 2, SZ / 2, RES)
X, Y = np.meshgrid(g, g)
R = np.hypot(X, Y)
wx = X + 90 * perlin(X / 500, Y / 500, 3); wy = Y + 90 * perlin(X / 500 + 7, Y / 500, 5)
def eroded(x, y, octaves, seed, step):
    """Ridged fbm where each octave is damped by the slope built so far: smooth valleys, sharp ridges, gullies."""
    tot = np.zeros_like(x); amp = 1.0; freq = 1.0; dx = np.zeros_like(x); dy = np.zeros_like(x)
    for o in range(octaves):
        pn = perlin(x * freq, y * freq, seed + o * 13)
        n = 1.0 - np.abs(pn); n = n * n
        gy_, gx_ = np.gradient(pn, step * freq)      # slope of the smooth noise, not of the creased ridge
        dx += gx_ * amp; dy += gy_ * amp
        tot += amp * n / (1.0 + 0.9 * (dx * dx + dy * dy))
        amp *= 0.52; freq *= 2.0
    return tot
step = (SZ / (RES - 1)) / 420.0
rid = eroded(wx / 420, wy / 420, 6 if RES < 1200 else 7, 11, step) * 1.25
def ss(a, b, x): t = np.clip((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t)
mount = ss(330, 660, R) * (90 + 190 * ss(500, 1200, R))
peak = 230 * np.exp(-(((X - 90) / 230) ** 2 + ((Y - 900) / 190) ** 2))      # the big one framed by the front windows
peak2 = 230 * np.exp(-(((X + 720) / 230) ** 2 + ((Y + 100) / 230) ** 2))
Z = mount * rid / 1.5 + (peak + peak2) * (0.45 + 0.55 * rid / 1.5)
valley = -40 + 3.0 * perlin(X / 140, Y / 140, 21) + 1.2 * perlin(X / 40, Y / 40, 22)       # the pavilion stands on a cliff above a lake
fh = ss(330, 560, R) * 16 * eroded(wx / 160, wy / 160, 5, 41, (SZ / (RES - 1)) / 160.0) / 1.3   # forested foothills
cliff = -0.6 - 6 * ss(24, 30, R) + (valley + 6.6) * ss(28, 48, R) + 3.0 * perlin(X / 9, Y / 9, 51) * ss(24, 34, R) * (1 - ss(40, 60, R))
terr = np.where(R < 24, -0.6, cliff) + fh
Z = Z + terr
verts = np.stack([X.ravel(), Y.ravel(), Z.ravel()], 1)
ii, jj = np.meshgrid(np.arange(RES - 1), np.arange(RES - 1))
a0 = (jj * RES + ii).ravel(); faces = np.stack([a0, a0 + 1, a0 + RES + 1, a0 + RES], 1)
me = bpy.data.meshes.new('terrain')
me.vertices.add(len(verts)); me.vertices.foreach_set('co', verts.astype(np.float32).ravel())
me.loops.add(faces.size); me.loops.foreach_set('vertex_index', faces.astype(np.int32).ravel())
me.polygons.add(len(faces)); me.polygons.foreach_set('loop_start', np.arange(0, faces.size, 4, dtype=np.int32))
me.update(calc_edges=True); me.validate()
me.polygons.foreach_set('use_smooth', np.ones(len(faces), dtype=bool))
me.materials.append(M_TERRAIN); link(bpy.data.objects.new('terrain', me))
