wb = node(Nw, 'ShaderNodeBump'); wb.inputs['Strength'].default_value = 0.05; Lw.new(wn.outputs['Fac'], wb.inputs['Height']); Lw.new(wb.outputs['Normal'], bw.inputs['Normal'])
