c = cam.constraints.new('TRACK_TO'); c.target = tgt; c.track_axis = 'TRACK_NEGATIVE_Z'; c.up_axis = 'UP_Y'
cam_d.dof.focus_object = tgt
def cam_at(t):
    e = smooth(t) * 0.75 + t * 0.25
    ang = math.radians(150 + 78 * e)                # front three-quarter -> behind
    rad = 4.0 + 0.2 * e
    p = Vector((rad * math.cos(ang), rad * math.sin(ang), 0.80 + 0.22 * e))
    p += Vector((0.02 * math.sin(t * 9.1), 0.015 * math.sin(t * 7.3 + 1), 0.012 * math.sin(t * 11.7 + 2)))   # breath of a handheld rig
    look = Vector((-0.7 * e * e, 0.2 + 1.7 * e * e, 0.95 + 0.10 * e))
    return p, look
for fr in range(0, END + 1, 2):
    p, look = cam_at(fr / END)
    cam.location = p; tgt.location = look
    cam.keyframe_insert('location', frame=fr); tgt.keyframe_insert('location', frame=fr)

