    resw = int(argv[2]) if len(argv) > 2 else 640
    spp = int(argv[3]) if len(argv) > 3 else 16
    sc.render.resolution_x = resw; sc.render.resolution_y = int(round(resw / ASPECT / 2)) * 2; sc.cycles.samples = spp
    os.makedirs(outd, exist_ok=True)
    if ':' in spec:
        a_, b_, c_ = (int(x) for x in spec.split(':')); frames = list(range(a_, min(b_, END), c_))
    else: frames = [int(x) for x in spec.split(',')]
    for fr in frames:
        p = os.path.join(outd, f'f{fr:04d}.png')
        if os.path.exists(p) and os.path.getsize(p) > 1000 and not os.environ.get('FORCE'): continue
        t0 = time.time(); sc.frame_set(fr); sc.render.filepath = p
        bpy.ops.render.render(write_still=True)
        print('DONE', fr, round(time.time() - t0, 1), flush=True)
